CURLcode close_curl_easy_handle(struct Curl_easy *data) {
    if (!data) {
        return CURLE_OK;
    }

    /* Clear timers associated with the handle */
    Curl_rem_time(data);

    /* Detach from a multi handle if part of one */
    if (data->multi) {
        Curl_remove_handle(data->multi, data);
    }

    /* Clean up any associated multi handles */
    if (data->multi_sub) {
        Curl_multi_close(data->multi_sub);
        data->multi_sub = NULL;
    }

    /* Destroy timeout list */
    if (data->tclist) {
        Curl_safefree(data->tclist);
        data->tclist = NULL;
    }

    /* Free allocated memory for states and configurations */
    Curl_safefree(data->wildcard);
    Curl_safefree(data->set.host);
    Curl_safefree(data->set.proxy);
    Curl_safefree(data->set.uh);
    Curl_safefree(data->set.rangeline);
    Curl_safefree(data->set.errorbuffer);
    Curl_safefree(data->progress.flags);

    /* Close SSL sessions */
    if (data->ssl) {
        Curl_ssl_close(data);
    }

    /* Clean up redirect information */
    if (data->change.url) {
        Curl_safefree(data->change.url);
    }

    /* Release resources related to share */
    if (data->share) {
        Curl_close_share(data->share);
        data->share = NULL;
    }

    /* Free the easy handle itself */
    Curl_safefree(data);

    return CURLE_OK;
}

CURLcode curl_easy_cleanup(struct Curl_easy *data) {
  if (!data)
    return CURLE_OK;

  /* Clear timers and detach from a multi handle if part of one */
  Curl_cleanup_timers(data);

  /* Clean up any associated multi handles */
  Curl_cleanup_multi_handles(data);

  /* Destroy timeout lists */
  Curl_timeout_list_destroy(data);

  /* Free allocated memory for states and configurations */
  Curl_safefree(data->state.path);
  Curl_safefree(data->set.str[STRING_URL]);

  /* Close SSL sessions */
  Curl_ssl_cleanup(data);

  /* Clean up redirect information */
  Curl_cleanup_cookies(data);
  Curl_cleanup_hsts(data);

  /* Release resources related to share and wildcard structures */
  if (data->share)
    Curl_share_cleanup(data->share);
  Curl_cleanup_wildcardmatch(data);

  /* Free the easy handle itself */
  Curl_safefree(data);

  return CURLE_OK;
}

